<?php
require_once 'config.php';require_login();$page_title='Sales';$pdo=db();
$rows=$pdo->query("SELECT d.*,a.name AS agent_name,(d.package_kg*d.quantity*d.price_per_kg) AS total FROM deliveries d JOIN agents a ON a.id=d.agent_id WHERE d.status='Delivered' ORDER BY d.delivery_date DESC,d.id DESC")->fetchAll();
$total=0;foreach($rows as $r)$total+=(float)$r['total'];
require 'includes/header.php';?><div class="shell"><?php require 'includes/sidebar.php';?><main class="main"><?php require 'includes/topbar.php';?><div class="content"><div class="page-heading"><div><div class="eyebrow">REVENUE</div><h1>Sales</h1><p>Sales are calculated from deliveries marked Delivered.</p></div></div><div class="cards"><div class="stat"><div class="stat-top">Total recorded sales <span class="stat-icon">₱</span></div><strong><?=money($total)?></strong><small><?=count($rows)?> delivered orders</small></div></div><div class="panel"><div class="panel-head"><h2>Sales ledger</h2><a class="btn btn-secondary" href="deliveries.php">＋ Add delivery</a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Agent</th><th>Package</th><th>Qty</th><th>Price/KG</th><th>Sales total</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">No delivered orders to report.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['delivery_date'])?></td><td><?=e($r['customer_name'])?></td><td><?=e($r['agent_name'])?></td><td><?=e($r['package_kg'])?> KG</td><td><?=e($r['quantity'])?></td><td><?=money($r['price_per_kg'])?></td><td><strong><?=money($r['total'])?></strong></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="6">TOTAL SALES</th><th><?=money($total)?></th></tr></tfoot></table></div></div></div><?php require 'includes/footer.php';?></main></div>
